pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, uint256 collectAmount) public {
        // Restrict unlockTime to a reasonable future and collectAmount to non-zero, but keep wide
        vm.assume(unlockTime > block.timestamp);
        vm.assume(collectAmount > 0 && collectAmount <= 1 ether);

        // Use a fresh actor to avoid state pollution from other fuzzer runs
        address actor = address(uint160(uint256(keccak256(abi.encode(unlockTime, collectAmount)))));
        uint256 deposit = 1 ether;
        vm.deal(actor, deposit);

        // Record balances before
        uint256 balBefore = address(c).balance;
        uint256 accBalBefore = c.Acc(actor).balance;

        // Actor deposits via Put
        vm.prank(actor);
        c.Put{value: deposit}(unlockTime);

        // Fast-forward past unlockTime so Collect is allowed
        vm.warp(unlockTime + 1);

        // Actor tries to Collect collectAmount
        bool ok = true;
        vm.prank(actor);
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }

        uint256 balAfter = address(c).balance;
        uint256 accBalAfter = c.Acc(actor).balance;

        // Invariant: the withdrawn ETH cannot exceed the amount originally deposited,
        // i.e., the contract balance after Collect is at least what it was before Put.
        // The bug allows reentrant fallback to double-count msg.value, inflating Acc balance
        // beyond the actual deposit, enabling a Collect that drains more ETH than deposited,
        // thus balAfter may fall below balBefore for some fuzz inputs.
        assertTrue(balAfter >= balBefore);
    }
}

