pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 reentryAmount) public {
        // Keep amounts in a plausible range (non-zero, not overflowing) to trigger the bug
        vm.assume(amount > 0 && amount < 1000 ether);
        vm.assume(reentryAmount > 0 && reentryAmount < 1000 ether);

        // Use the test contract itself as the attacker that can reenter
        // First, Put enough balance to be able to Collect
        vm.deal(address(this), amount + reentryAmount);
        c.Put{value: amount}(0);
        // Warp past unlock time to allow Collect
        vm.warp(block.timestamp + 1);

        // Record the initial balance after Put
        uint256 initialBalance = c.Acc(address(this)).balance;

        // Execute Collect; a malicious fallback will re-enter Collect
        c.Collect(amount);

        // After the call(s), observe the final balance
        uint256 finalBalance = c.Acc(address(this)).balance;

        // General rule: after a single external Collect request for `amount`,
        // the balance is exactly initialBalance - amount (i.e., no extra deduction).
        // The buggy version allows reentrancy, leading to extra deductions.
        assertTrue(finalBalance == initialBalance - amount);
    }

    // Attacker's fallback: reenters Collect with a second amount, only in buggy version
    fallback() external payable {
        // Only re-enter once to trigger the bug; use a convention that avoids infinite loops
        // The fuzzer provides reentryAmount; use it here
        c.Collect(reentryAmount);
    }

    receive() external payable {}
}

